  8	import com.pousadamarealta.database.DatabaseManager;
  9	import com.pousadamarealta.database.RoomDAO;
 10	import com.pousadamarealta.domain.ReservationEventDispatcher;
 11	import com.pousadamarealta.service.FinanceNotificationListener;
 12	import com.pousadamarealta.service.GovernanceNotificationListener;
 13	import io.javalin.Javalin;
 14	
 15	public class App {
 16	    public static void main(String[] args) {
 17	        String dbUrl = System.getenv("DB_URL");
 18	        String dbUser = System.getenv("DB_USER");
 19	        String dbPassword = System.getenv("DB_PASSWORD");
 20	        String portStr = System.getenv("PORT");
 21	        int port = portStr != null ? Integer.parseInt(portStr) : 7070;
 22	
 23	        if (dbUrl == null || dbUser == null || dbPassword == null) {
 24	            throw new RuntimeException("Database environment variables not set");
 25	        }
 26	
 27	        DatabaseManager.initialize(dbUrl, dbUser, dbPassword);
 28	
 29	        try {
 30	            RoomDAO.getInstance().initialize();
 31	        } catch (Exception e) {
 32	            throw new RuntimeException("Failed to initialize rooms", e);
 33	        }
 34	
 35	        ReservationEventDispatcher.getInstance().addListener(new GovernanceNotificationListener());
 36	        ReservationEventDispatcher.getInstance().addListener(new FinanceNotificationListener());
 37	
 38	        Javalin app = Javalin.create()
 39	                .start(port);
 40	
 41	        app.get("/rooms", RoomsHandler::getRooms);
 42	
 43	        app.post("/reservations", ReservationsHandler::createReservation);
 44	        app.get("/reservations/{id}", ReservationsHandler::getReservation);
 45	        app.post("/reservations/{id}/confirmation", ReservationsHandler::confirmReservation);
 46	        app.post("/reservations/{id}/cancellation", ReservationsHandler::cancelReservation);
 47	        app.post("/reservations/{id}/check-in", ReservationsHandler::checkIn);
 48	        app.post("/reservations/{id}/check-out", ReservationsHandler::checkOut);
 49	        app.get("/reservations/{id}/document", ReservationsHandler::getDocument);
 50	
 51	        app.get("/messages", MessagesHandler::getMessages);
 52	
 53	        app.get("/reports/occupancy", ReportsHandler::getOccupancyReport);
 54	        app.get("/reports/revenue", ReportsHandler::getRevenueReport);
 55	
 56	        app.exception(Exception.class, ApiErrorHandler::handleException);
 57	
 58	        System.out.println("Server started on port " + port);
 59	    }
 60	}
