 67	public class ApiErrorHandler {
 68	    public static void handleException(Exception e, Context ctx) {
 69	        e.printStackTrace();
 70	        ctx.status(HttpStatus.INTERNAL_SERVER_ERROR);
 71	        ctx.json(Map.of(
 72	                "error", "INTERNAL_SERVER_ERROR",
 73	                "message", e.getMessage() != null ? e.getMessage() : "Internal server error"
 74	        ));
 75	    }
 76	}
