106	import com.pousadamarealta.service.ReportService;
107	import io.javalin.http.Context;
108	import io.javalin.http.HttpStatus;
109	import java.time.LocalDate;
110	import java.time.YearMonth;
111	import java.time.format.DateTimeFormatter;
112	import java.util.Map;
113	
114	public class ReportsHandler {
115	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ISO_DATE;
116	
117	    public static void getOccupancyReport(Context ctx) throws Exception {
118	        String dateStr = ctx.queryParam("date");
119	
120	        if (dateStr == null || dateStr.isEmpty()) {
121	            ctx.status(HttpStatus.BAD_REQUEST);
122	            ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Missing date parameter"));
123	            return;
124	        }
125	
126	        try {
127	            LocalDate date = LocalDate.parse(dateStr, DATE_FORMATTER);
128	            String report = ReportService.getInstance().generateOccupancyReport(date);
129	            ctx.contentType("text/csv; charset=utf-8");
130	            ctx.result(report);
131	        } catch (Exception e) {
132	            ctx.status(HttpStatus.BAD_REQUEST);
133	            ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Invalid date format"));
134	        }
135	    }
136	
137	    public static void getRevenueReport(Context ctx) throws Exception {
138	        String monthStr = ctx.queryParam("month");
139	
140	        if (monthStr == null || monthStr.isEmpty()) {
141	            ctx.status(HttpStatus.BAD_REQUEST);
142	            ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Missing month parameter"));
143	            return;
144	        }
145	
146	        try {
147	            YearMonth month = YearMonth.parse(monthStr, DateTimeFormatter.ofPattern("yyyy-MM"));
148	            String report = ReportService.getInstance().generateRevenueReport(month);
149	            ctx.contentType("text/csv; charset=utf-8");
150	            ctx.result(report);
151	        } catch (Exception e) {
152	            ctx.status(HttpStatus.BAD_REQUEST);
153	            ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Invalid month format"));
154	        }
155	    }
156	}
