165	import com.pousadamarealta.service.ReservationService;
166	import io.javalin.http.Context;
167	import io.javalin.http.HttpStatus;
168	import java.time.LocalDate;
169	import java.time.format.DateTimeFormatter;
170	import java.util.HashMap;
171	import java.util.Map;
172	
173	public class ReservationsHandler {
174	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ISO_DATE;
175	
176	    public static void createReservation(Context ctx) throws Exception {
177	        JsonNode body = ctx.bodyAsClass(JsonNode.class);
178	
179	        if (!body.hasNonNull("roomNumber") || !body.hasNonNull("guestName") ||
180	            !body.hasNonNull("guestEmail") || !body.hasNonNull("guestCpf") ||
181	            !body.hasNonNull("checkIn") || !body.hasNonNull("checkOut") ||
182	            !body.hasNonNull("guests") || !body.hasNonNull("ratePlan")) {
183	            ctx.status(HttpStatus.BAD_REQUEST);
184	            ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Missing required fields"));
185	            return;
186	        }
187	
188	        int roomNumber = body.get("roomNumber").asInt();
189	        String guestName = body.get("guestName").asText();
190	        String guestEmail = body.get("guestEmail").asText();
191	        String guestCpf = body.get("guestCpf").asText();
192	        LocalDate checkIn = LocalDate.parse(body.get("checkIn").asText(), DATE_FORMATTER);
193	        LocalDate checkOut = LocalDate.parse(body.get("checkOut").asText(), DATE_FORMATTER);
194	        int guests = body.get("guests").asInt();
195	        String ratePlan = body.get("ratePlan").asText();
196	
197	        Room room = RoomDAO.getInstance().getRoomByNumber(roomNumber);
198	        if (room == null) {
199	            ctx.status(HttpStatus.NOT_FOUND);
200	            ctx.json(Map.of("error", "ROOM_NOT_FOUND", "message", "Room not found"));
201	            return;
202	        }
203	
204	        if (guests < 1 || guests > room.getCapacity()) {
205	            ctx.status(422);
206	            ctx.json(Map.of("error", "CAPACITY_EXCEEDED", "message", "Guest count exceeds room capacity"));
207	            return;
208	        }
209	
210	        if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
211	            ctx.status(HttpStatus.BAD_REQUEST);
212	            ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Check-out must be after check-in"));
213	            return;
214	        }
215	
216	        if (!ReservationService.getInstance().isRoomAvailable(roomNumber, checkIn, checkOut)) {
217	            ctx.status(HttpStatus.CONFLICT);
218	            ctx.json(Map.of("error", "ROOM_UNAVAILABLE", "message", "Room not available for these dates"));
219	            return;
220	        }
221	
222	        Reservation reservation = ReservationService.getInstance().createReservation(
223	                roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests, ratePlan);
224	
225	        ctx.status(HttpStatus.CREATED);
226	        ctx.json(mapReservation(reservation));
227	    }
228	
229	    public static void getReservation(Context ctx) throws Exception {
230	        long id = Long.parseLong(ctx.pathParam("id"));
231	        Reservation reservation = ReservationService.getInstance().getReservation(id);
232	
233	        if (reservation == null) {
234	            ctx.status(HttpStatus.NOT_FOUND);
235	            ctx.json(Map.of("error", "RESERVATION_NOT_FOUND", "message", "Reservation not found"));
236	            return;
237	        }
238	
239	        ctx.json(mapReservation(reservation));
240	    }
241	
242	    public static void confirmReservation(Context ctx) throws Exception {
243	        long id = Long.parseLong(ctx.pathParam("id"));
244	        JsonNode body = ctx.bodyAsClass(JsonNode.class);
245	
246	        if (!body.hasNonNull("amountPaid")) {
247	            ctx.status(HttpStatus.BAD_REQUEST);
248	            ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Missing amountPaid"));
249	            return;
250	        }
251	
252	        Reservation reservation = ReservationService.getInstance().getReservation(id);
253	        if (reservation == null) {
254	            ctx.status(HttpStatus.NOT_FOUND);
255	            ctx.json(Map.of("error", "RESERVATION_NOT_FOUND", "message", "Reservation not found"));
256	            return;
257	        }
258	
259	        if (reservation.getStatus().getCode().equals("PENDING")) {
260	            try {
261	                Money amountPaid = Money.of(body.get("amountPaid").asDouble());
262	                reservation = ReservationService.getInstance().confirmReservation(id, amountPaid);
263	                ctx.json(mapReservation(reservation));
264	            } catch (RuntimeException e) {
265	                ctx.status(HttpStatus.CONFLICT);
266	                ctx.json(Map.of("error", "OPERATION_NOT_ALLOWED", "message", e.getMessage()));
267	            }
268	        } else {
269	            ctx.status(HttpStatus.CONFLICT);
270	            ctx.json(Map.of("error", "OPERATION_NOT_ALLOWED", "message", "Cannot confirm non-pending reservation"));
271	        }
272	    }
273	
274	    public static void cancelReservation(Context ctx) throws Exception {
275	        long id = Long.parseLong(ctx.pathParam("id"));
276	        Reservation reservation = ReservationService.getInstance().getReservation(id);
277	
278	        if (reservation == null) {
279	            ctx.status(HttpStatus.NOT_FOUND);
280	            ctx.json(Map.of("error", "RESERVATION_NOT_FOUND", "message", "Reservation not found"));
281	            return;
282	        }
283	
284	        try {
285	            reservation = ReservationService.getInstance().cancelReservation(id);
286	            ctx.json(mapReservation(reservation));
287	        } catch (RuntimeException e) {
288	            ctx.status(HttpStatus.CONFLICT);
289	            ctx.json(Map.of("error", "OPERATION_NOT_ALLOWED", "message", e.getMessage()));
290	        }
291	    }
292	
293	    public static void checkIn(Context ctx) throws Exception {
294	        long id = Long.parseLong(ctx.pathParam("id"));
295	        Reservation reservation = ReservationService.getInstance().getReservation(id);
296	
297	        if (reservation == null) {
298	            ctx.status(HttpStatus.NOT_FOUND);
299	            ctx.json(Map.of("error", "RESERVATION_NOT_FOUND", "message", "Reservation not found"));
300	            return;
301	        }
302	
303	        try {
304	            reservation = ReservationService.getInstance().checkIn(id);
305	            ctx.json(mapReservation(reservation));
306	        } catch (RuntimeException e) {
307	            ctx.status(HttpStatus.CONFLICT);
308	            ctx.json(Map.of("error", "OPERATION_NOT_ALLOWED", "message", e.getMessage()));
309	        }
310	    }
311	
312	    public static void checkOut(Context ctx) throws Exception {
313	        long id = Long.parseLong(ctx.pathParam("id"));
314	        Reservation reservation = ReservationService.getInstance().getReservation(id);
315	
316	        if (reservation == null) {
317	            ctx.status(HttpStatus.NOT_FOUND);
318	            ctx.json(Map.of("error", "RESERVATION_NOT_FOUND", "message", "Reservation not found"));
319	            return;
320	        }
321	
322	        try {
323	            reservation = ReservationService.getInstance().checkOut(id);
324	            ctx.json(mapCheckOutResponse(reservation));
325	        } catch (RuntimeException e) {
326	            ctx.status(HttpStatus.CONFLICT);
327	            ctx.json(Map.of("error", "OPERATION_NOT_ALLOWED", "message", e.getMessage()));
328	        }
329	    }
330	
331	    public static void getDocument(Context ctx) throws Exception {
332	        long id = Long.parseLong(ctx.pathParam("id"));
333	        Reservation reservation = ReservationService.getInstance().getReservation(id);
334	
335	        if (reservation == null) {
336	            ctx.status(HttpStatus.NOT_FOUND);
337	            ctx.json(Map.of("error", "RESERVATION_NOT_FOUND", "message", "Reservation not found"));
338	            return;
339	        }
340	
341	        if (reservation.getAmountPaid().toDouble() == 0) {
342	            ctx.status(HttpStatus.CONFLICT);
343	            ctx.json(Map.of("error", "OPERATION_NOT_ALLOWED", "message", "Document only available for paid reservations"));
344	            return;
345	        }
346	
347	        ctx.json(mapDocument(reservation));
348	    }
349	
350	    private static Map<String, Object> mapReservation(Reservation res) {
351	        Map<String, Object> map = new HashMap<>();
352	        map.put("id", res.getId());
353	        map.put("roomNumber", res.getRoomNumber());
354	        map.put("guestName", res.getGuestName());
355	        map.put("guestEmail", res.getGuestEmail());
356	        map.put("guestCpf", res.getGuestCpf());
357	        map.put("checkIn", res.getCheckIn().format(DATE_FORMATTER));
358	        map.put("checkOut", res.getCheckOut().format(DATE_FORMATTER));
359	        map.put("guests", res.getGuests());
360	        map.put("ratePlan", res.getRatePlan().getCode());
361	        map.put("nights", res.getNights());
362	        map.put("subtotal", Math.round(res.getSubtotal().toDouble() * 100) / 100.0);
363	        map.put("discount", Math.round(res.getDiscount().toDouble() * 100) / 100.0);
364	        map.put("total", Math.round(res.getTotal().toDouble() * 100) / 100.0);
365	        map.put("status", res.getStatus().getCode());
366	        map.put("amountPaid", Math.round(res.getAmountPaid().toDouble() * 100) / 100.0);
367	        map.put("refund", res.getRefund() != null ? Math.round(res.getRefund().toDouble() * 100) / 100.0 : null);
368	        return map;
369	    }
370	
371	    private static Map<String, Object> mapCheckOutResponse(Reservation res) {
372	        return mapReservation(res);
373	    }
374	
375	    private static Map<String, Object> mapDocument(Reservation res) {
376	        String roomType;
377	        if (res.getRoomNumber() < 200) {
378	            roomType = "STANDARD";
379	        } else if (res.getRoomNumber() < 300) {
380	            roomType = "DELUXE";
381	        } else {
382	            roomType = "SUITE";
383	        }
384	
385	        Map<String, Object> map = new HashMap<>();
386	        map.put("title", "Comprovante de reserva");
387	        map.put("reservationId", res.getId());
388	        map.put("guestName", res.getGuestName());
389	        map.put("guestCpf", res.getGuestCpf());
390	        map.put("roomNumber", res.getRoomNumber());
391	        map.put("roomType", roomType);
392	        map.put("checkIn", res.getCheckIn().format(DATE_FORMATTER));
393	        map.put("checkOut", res.getCheckOut().format(DATE_FORMATTER));
394	        map.put("nights", res.getNights());
395	        map.put("subtotal", Math.round(res.getSubtotal().toDouble() * 100) / 100.0);
396	        map.put("discount", Math.round(res.getDiscount().toDouble() * 100) / 100.0);
397	        map.put("total", Math.round(res.getTotal().toDouble() * 100) / 100.0);
398	        return map;
399	    }
400	}
