350	    private static Map<String, Object> mapReservation(Reservation res) {
351	        Map<String, Object> map = new HashMap<>();
352	        map.put("id", res.getId());
353	        map.put("roomNumber", res.getRoomNumber());
354	        map.put("guestName", res.getGuestName());
355	        map.put("guestEmail", res.getGuestEmail());
356	        map.put("guestCpf", res.getGuestCpf());
357	        map.put("checkIn", res.getCheckIn().format(DATE_FORMATTER));
