482	    23	
483	    24	        if (month == Month.DECEMBER && dayOfMonth >= 15) {
484	    25	            return true;
485	    26	        }
486	    27	
487	    28	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
488	    29	            return true;
489	    30	        }
