     6	public class SeasonalityCalculator {
     7	    private static final double HIGH_SEASON_MULTIPLIER = 1.20;
     8	
     9	    public static Money calculateNightlyRate(double baseRate, LocalDate night) {
    10	        if (isHighSeason(night)) {
    11	            return Money.of(baseRate * HIGH_SEASON_MULTIPLIER);
    12	        }
    13	        return Money.of(baseRate);
    14	    }
    15	
    16	    private static boolean isHighSeason(LocalDate date) {
    17	        Month month = date.getMonth();
    18	        int dayOfMonth = date.getDayOfMonth();
    19	
    20	        if (month == Month.JULY) {
    21	            return true;
    22	        }
    23	
    24	        if (month == Month.DECEMBER && dayOfMonth >= 15) {
    25	            return true;
    26	        }
    27	
    28	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
    29	            return true;
    30	        }
    31	
    32	        return false;
    33	    }
    34	}
