    21	    public static String generateReceipt(Reservation reservation) throws Exception {
    22	        StringBuilder sb = new StringBuilder();
    23	        sb.append(String.format("Comprovante de reserva nº %d\n", reservation.getId()));
    24	        sb.append(String.format("Hóspede: %s (CPF %s)\n", reservation.getGuestName(), formatCpf(reservation.getGuestCpf())));
    25	
    26	        Room room = RoomDAO.getInstance().getRoomByNumber(reservation.getRoomNumber());
    27	        String roomType = room != null ? room.getTypeCode() : getRoomTypeByNumber(reservation.getRoomNumber());
