    29	
    30	        String checkIn = reservation.getCheckIn().format(DATE_FORMATTER);
    31	        String checkOut = reservation.getCheckOut().format(DATE_FORMATTER);
    32	        String nightsLabel = reservation.getNights() == 1 ? "diária" : "diárias";
    33	        sb.append(String.format("Entrada: %s | Saída: %s | %d %s\n", checkIn, checkOut, reservation.getNights(), nightsLabel));
    34	
    35	        sb.append(String.format("Diárias: %s\n", formatMoney(reservation.getSubtotal())));
    36	        if (reservation.getDiscount().toDouble() > 0) {
    37	            sb.append(String.format("Desconto: %s\n", formatMoney(reservation.getDiscount())));
