    58	
    59	        LocalDate monthStart = month.atDay(1);
    60	        LocalDate monthEnd = month.atEndOfMonth().plusDays(1);
    61	
    62	        List<Reservation> reservations = ReservationDAO.getInstance()
    63	                .getReservationsByDateRange(monthStart, monthEnd);
    64	
    65	        double total = 0;
    66	        for (Reservation res : reservations) {
    67	            double amount = calculateAmount(res);
    68	            csv.append(String.format("%d,%d,%s,%s,%s,%.2f\n",
    69	                    res.getId(),
    70	                    res.getRoomNumber(),
    71	                    formatDate(res.getCheckIn()),
    72	                    formatDate(res.getCheckOut()),
    73	                    res.getStatus().getCode(),
    74	                    amount));
    75	            total += amount;
    76	        }
    77	
    78	        csv.append(String.format("total,%.2f\n", total));
    79	        return csv.toString();
